class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        res = 0
        for i in range(n):
            cnt = {}
            cons = 0
            for j in range(i, n):
                ch = word[j]
                if ch in 'aeiou':
                    cnt[ch] = cnt.get(ch, 0) + 1
                else:
                    cons += 1
                if cons > k:
                    break
                if cons == k and len(cnt) == 5:
                    res += 1
        return res

