from collections import defaultdict
class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def f(K):
            cnt = defaultdict(int)
            cons = 0
            res = 0
            l = 0
            for r, ch in enumerate(word):
                if ch in 'aeiou':
                    cnt[ch] += 1
                else:
                    cons += 1
                while len(cnt) == 5 and cons >= K:
                    out = word[l]
                    if out in 'aeiou':
                        cnt[out] -= 1
                        if cnt[out] == 0:
                            del cnt[out]
                    else:
                        cons -= 1
                    l += 1
                res += l
            return res
        return f(k) - f(k + 1)

