class Solution {
public:
    long long f(const string& w, int K) {
        int cnt[5] = {0};
        int kinds = 0, cons = 0;
        long long res = 0;
        int l = 0, n = w.size();
        string vow = "aeiou";
        for (int r = 0; r < n; r++) {
            int v = vow.find(w[r]);
            if (v >= 0) { if (cnt[v]++ == 0) kinds++; }
            else cons++;
            while (kinds == 5 && cons >= K) {
                int o = vow.find(w[l]);
                if (o >= 0) { if (--cnt[o] == 0) kinds--; }
                else cons--;
                l++;
            }
            res += l;
        }
        return res;
    }
    long long countOfSubstrings(string word, int k) {
        return f(word, k) - f(word, k + 1);
    }
};

